-- Makes a plan activity a usable step-by-step card instead of one paragraph:
-- an ordered list of steps, what materials to gather first (empty array for
-- "nothing needed"), and a rough time estimate. Generated by the plan prompt
-- (prompts/plan.ts) alongside the existing title/instructions.

alter table plan_activities
  add column steps             text[] not null default '{}',
  add column materials         text[] not null default '{}',
  add column estimated_minutes int;
